query:
query queued_object {
 match "architecture.batch-work-queue.drain"(unit:$invoker,input:$input,dispatch:$dispatch);
 require $unit HAS_METHOD $execute;
 callable(constructor: false, arity: 0) as $execute;
 require $unit HAS_FIELD $receiver;
 require $receiver CONSTRUCTOR_FIELD_INPUT $receiver_input;
 require $unit HAS_METHOD $constructor;
 require $constructor HAS_PARAMETER $receiver_input;
 require $execute HAS_CALL $work;
 require $work RECEIVER $receiver;
 different $unit $invoker;
 any {
  require $input TYPE $contract;
  path $unit SUBTYPE_OF{0,8} $contract as $contract_path;
  require $contract HAS_METHOD $slot;
  callable(arity: 0) as $slot;
  where $dispatch.name == $slot.name;
  any { require $execute OVERRIDES $slot; }
  or { require $contract HAS_METHOD $execute; where $execute.name == $slot.name; }
 } or {
  parameter(type_state: unknown) as $input;
  require $usage CALL_BINDING $binding [mode: direct];
  require $binding BINDING_PARAMETER $input;
  require $binding BINDING_VALUE $provided;
  any { require $provided ALLOCATES_TYPE $unit; }
  or { require $provided TYPE $unit; }
  where $dispatch.name == $execute.name;
 }
 emit $unit, $execute, $receiver, $constructor, $receiver_input, $work, $invoker, $input, $dispatch;
}

